#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,re,runpy

runpy.run_path("ci/generate_chatgpt_webview_v46_slider_write_restore.py", run_name="__main__")
ROOT=Path("runtime_probes/chatgpt-webview-stable-probe")
PKG=ROOT/"app/src/main/java/com/homayounisaghar/chatgptwebviewprobe"
BLOB=''
SRC=PKG/"OrchestratorPaidModelEffortCrossSurfaceReceiptV47Activity.java"
SRC.write_bytes(zlib.decompress(base64.b64decode(BLOB)))
cfg=PKG/"TelemetryConfigV47.java"
cfg.write_text('package com.homayounisaghar.chatgptwebviewprobe;\n\npublic final class TelemetryConfigV47 {\n    public static final boolean CONFIGURED=false;\n    public static final String WEBHOOK_URL="";\n    public static final String SOURCE_REF="";\n    public static final String COLLECTOR_ID="";\n    private TelemetryConfigV47() {}\n    public static boolean isConfigured() { return CONFIGURED && WEBHOOK_URL.startsWith("https://") && !COLLECTOR_ID.isEmpty(); }\n}\n')
gradle=ROOT/"app/build.gradle"
g=gradle.read_text()
assert "versionCode 47" in g
assert "versionName '0.44-stable-diag-medium-light-restore-probe'" in g
g=g.replace("versionCode 47","versionCode 48",1)
g=g.replace("versionName '0.44-stable-diag-medium-light-restore-probe'","versionName '0.45-stable-diag-cross-surface-light-receipt'",1)
gradle.write_text(g)
man=ROOT/"app/src/main/AndroidManifest.xml"
m=man.read_text()
old="OrchestratorPaidModelEffortSliderArrowLeftRestoreV46Activity"
new="OrchestratorPaidModelEffortCrossSurfaceReceiptV47Activity"
assert old in m
m=m.replace(old,new,1)
man.write_text(m)
s=SRC.read_text()
body=re.sub(r'/\*.*?\*/','',s,flags=re.S)
body=re.sub(r'//.*','',body)
assert "PASS_MACHINE_VERIFIED_LIGHT_APPLIED_AND_MEDIUM_RESTORED" in s
assert "PASS_CLOSED_COMPOSER_LIGHT" in s
assert "PASS_CLOSED_LIGHT_REOPENED_SAME_SLIDER_VALUE_0" in s
assert "PASS_CLOSED_COMPOSER_MEDIUM" in s
assert body.count("new PointerEvent('pointerdown'") == 1
assert body.count("new KeyboardEvent('keydown'") == 1
assert ".click()" not in body
assert "pointerover" not in body and "mouseover" not in body
assert "elementFromPoint" not in body
assert "setAttribute(\"aria-value" not in body
print("PASS v0.45 cross-surface machine receipt generator")
